-- PBI-010: tipos de vehículo y precio base de cada servicio según el tipo.
-- Aditivo: no modifica tablas existentes.
create table if not exists public.tipos_vehiculos (
  "Id_Tipos_Vehiculos" integer generated by default as identity primary key,
  "Descripcion" varchar(100) not null unique,
  "Activo" boolean not null default true
);

create table if not exists public.precios_servicios (
  "Id_Precios_Servicios" integer generated by default as identity primary key,
  "Id_Productos" integer not null references public.productos("Id_Productos") on delete cascade,
  "Id_Tipos_Vehiculos" integer not null references public.tipos_vehiculos("Id_Tipos_Vehiculos") on delete restrict,
  "Precio" numeric(18,0) not null check ("Precio" >= 0),
  "FechaActualizacion" timestamp not null default now(),
  "Id_Usuarios" integer not null references public.usuarios("Id_Usuarios"),
  constraint precios_servicios_unico unique ("Id_Productos", "Id_Tipos_Vehiculos")
);

insert into public.tipos_vehiculos ("Descripcion")
values ('Moto'), ('Auto'), ('Camioneta'), ('Furgón / Utilitario')
on conflict ("Descripcion") do nothing;
